ST.xhtml:p:
R_TriggerOpen(CLK := g_biSupportCylinderOpen);
R_TriggerClose(CLK := g_biSupportCylinderClose);

IF R_TriggerOpen.Q THEN
  nSupportState := 1;
  g_boSupportCylinderDone1 := FALSE;
  g_boSupportCylinderDone2 := FALSE;
END_IF;

IF R_TriggerClose.Q THEN
  g_boSupportCylinderDone1 := FALSE;
  IF nSupportState = 30 THEN
    nSupportState := 40;
  ELSE
    nSupportState := 0;
    g_boSupportCylinderDone2 := TRUE;
  END_IF;
END_IF;


CASE nSupportState OF
  0:
    nSupportState := 0;
  1:
    IF g_fPartLenght > dCyl1PartLength THEN
      g_boSupportCylinder1 := TRUE;
      nSupportState := 10;
    ELSE
      nSupportState := 20;
    END_IF;
  10:
    IF g_bSupportInPlaceEnable THEN
      IF g_bSupport1UpInPlace THEN
        nSupportState := 20;
      END_IF;
    ELSE
      Delay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dSupportInPlaceDelay)));
      IF Delay.Q THEN
        Delay(IN :=FALSE);
        nSupportState := 20;
      END_IF;
    END_IF;
  20:
    IF bCutStickEnable THEN
      g_boSupportCylinder2 := TRUE;
      IF g_bSupportInPlaceEnable THEN
        IF g_bSupport2UpInPlace THEN
          nSupportState := 30;
        END_IF;
      ELSE
        Delay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dSupportInPlaceDelay)));
        IF Delay.Q THEN
          Delay(IN :=FALSE);
          nSupportState := 30;
        END_IF;
      END_IF;
    ELSE
      nSupportState := 30;
    END_IF;
  30:
    g_boSupportCylinderDone1 := TRUE;
  40:
    nSupportState := 60;
    IF g_fPartLenght > dCyl1PartLength THEN
      g_boSupportCylinder1 := FALSE;
      nSupportState := 50;
    END_IF;
    IF bCutStickEnable THEN
      g_boSupportCylinder2 := FALSE;
      nSupportState := 50;
    END_IF;
  50:
    IF g_bSupportInPlaceEnable THEN
      IF NOT ((g_fPartLenght > dCyl1PartLength AND (NOT g_bSupport1DownInPlace)) OR
         (bCutStickEnable AND (NOT g_bSupport2DownInPlace))) THEN
        nSupportState := 60;
      END_IF;
    ELSE
      Delay(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(g_dSupportInPlaceDelay)));
      IF Delay.Q THEN
        Delay(IN :=FALSE);
        nSupportState := 60;
      END_IF;
    END_IF;
  60:
    g_boSupportCylinderDone2 := TRUE;
    nSupportState := 0;
END_CASE;

IF (Axis_Sensor.NCTOPLC.ACTPOS + dZCDistance) <= dCyl1AvoidDistance THEN
  g_boSupportCylinder1 := FALSE;
END_IF;

IF (Axis_Sensor.NCTOPLC.ACTPOS + dZCDistance) <= dCyl1SafeDistance THEN
  IF g_bSupportInPlaceEnable THEN
    IF NOT g_bSupport1DownInPlace THEN
      g_bQRCyl1Warn := TRUE;
    END_IF;
  ELSE
    IF g_boSupportCylinder1 THEN
      g_bQRCyl1Warn := TRUE;
    END_IF;
  END_IF;
END_IF;

IF g_bPlcResetBuffer THEN
  g_boSupportCylinder1 := FALSE;
  g_boSupportCylinder2 := FALSE;
  g_boSupportCylinder3 := FALSE;
  g_boSupportCylinder4 := FALSE;
  g_boSupportCylinderDone1 := FALSE;
  g_boSupportCylinderDone2 := FALSE;
  nSupportState := 0;
END_IF;
